# aeneid-061 (VIII.407-519): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Officina Volcani. Euandri consilium'
PART = "Vulcan's Forge and Evander's Offer (VIII.407–519)"
TITLE_EN = "Vulcan's Forge and Evander's Offer — Aeneid VIII.407–519"
ABOUT = ("At midnight, at the hour when a poor woman who lives by her spinning gets up to rake the embers and set her maids to "
"work, so that she can keep her marriage honest and bring up her children, Vulcan rises from his wife's soft bed and goes to "
"his workshop. It lies under a smoking island beside Lipari, off the coast of Sicily, where the Cyclopes' anvils boom in the "
"caverns and the iron hisses in the furnaces. There the Cyclopes, Brontes, Steropes and Pyragmon, are busy with three jobs "
"at once: a thunderbolt for Jupiter, half finished, built up out of rays of hail, rain-cloud, fire and wind; a chariot for "
"Mars; and the aegis of Pallas Athena, with its snakes and the Gorgon's severed head. Vulcan tells them to drop everything: "
"arms are wanted for a fighting man. They share out the work, and the bronze and gold flow and the steel melts as they shape "
"a huge shield of seven layers, working the bellows, quenching the hissing metal and swinging their hammers in time. Virgil "
"is rewriting the scene in Iliad 18 where Hephaestus forges new armour for Achilles. Meanwhile, at dawn, in Pallanteum, the "
"birds wake old Evander, who dresses, straps on his sword and comes out with his two watchdogs to find Aeneas. In private he "
"tells him the news. His own strength is small, but there is help at hand: the Etruscans of Agylla have thrown out their "
"king, Mezentius, a tyrant who used to kill men by tying them face to face with corpses, and he has taken refuge with "
"Turnus. All Etruria is up in arms to get him back for punishment, but a soothsayer has told them that no Italian may lead "
"them, and their king Tarchon has offered the command to Evander, who is too old for it. Evander's own son is half Sabine "
"and so ruled out. Aeneas, a foreigner whom the fates call, must take the command, and Evander will send Pallas with him, "
"with two hundred Arcadian horsemen, to learn the work of war under him.")

U = [
(410, 'ignes,',
 "Then, when first rest, in the middle now of the night driven on\nits course, had driven out sleep, at the time a woman first,\non whom to sustain by the distaff her life and by slender Minerva\nit is laid, the ash and the slumbering rouses fires,",
 "Then, at the hour when the first sleep has done its work and banished sleep, with night's chariot now half-way along its course, the hour when a woman whose lot it is to keep herself alive by her distaff and the fine work of Minerva first wakes the ashes and the sleeping fire,",
 """A new paragraph in Greenough. A comma-ended unit: the sentence runs to 415, and the simile of the working woman is split at its commas. 'Inde ubi', 'then, when'. 'prima quies… expulerat somnum', 'first rest had driven out sleep': the first sleep of the night has refreshed him and is over. 'medio… curriculo', 'in the middle of its course', ablative of time, with 'noctis abactae', 'of the night driven on', the night pictured as a chariot driven along its track; so 'at midnight'. 'cum femina primum… suscitat', 'when a woman first rouses', the time of day defined by what a working woman does. 'cui… impositum (est)', 'on whom it has been laid', impersonal, with 'tolerare… vitam', 'to sustain her life'. 'colo', 'by the distaff', and 'tenui… Minerva', 'by slender Minerva', the goddess of spinning and weaving standing for the craft itself, its fine thread. 'cinerem et sopitos… ignes', 'the ash and the slumbering fires', the embers banked overnight. Homer has a simile of an honest working woman weighing out wool to earn a meagre wage for her children (Iliad 12, from memory). Elisions 'Ind(e) ubi', 'ciner(em) et'."""),
(413, 'natos:',
 "adding the night to the work, and her maids by the lamps at a long\nkeeps busy task, so that chaste she may keep the bed\nof her husband and may be able her little to rear sons:",
 "adding the night to her day's work, and keeps her maids toiling by lamplight at a long stint of spinning, so that she can keep her husband's bed chaste and bring up her little children:",
 """'noctem addens operi', 'adding the night to her work', 'operi' dative with 'addens'. 'famulas… exercet', 'keeps her maids at work'. 'ad lumina', 'by the lamps'. 'longo… penso', 'at a long task', framing 'exercet'; 'pensum' (from 'pendo', 'weigh') is the weight of wool weighed out to a spinner as her day's work. 'ut… possit', purpose, with two infinitives: 'castum… servare cubile coniugis', 'to keep her husband's bed chaste', i.e. to live honestly without having to sell herself, and 'parvos educere natos', 'to rear her small children'. 'castum… cubile', framing 'ut servare'. 'coniugis' is 'con-iu-gis', the i a consonant. The colon closes the simile; the comparison comes next. Elisions 'noct(em) addens', 'famulasqu(e) ad', 'cast(um) ut'."""),
(415, 'surgit.',
 "not otherwise the Fire-lord, nor at that time more sluggish,\nfrom soft coverlets to his works of the smithy rises.",
 "just so the Lord of Fire, and no more slothful at that hour, rose from his soft bed to the labours of his forge.",
 """'haud secus', 'not otherwise', 'just so', the second half of the simile. 'Ignipotens', 'mighty in fire', Vulcan's title, used as a name. 'nec… segnior', 'no more sluggish', litotes: as early and as eager as the poor woman. 'tempore… illo', 'at that time', ablative of time. 'mollibus e stratis', 'from his soft coverlets', the bed where Venus has just won him over (8.405–406): the god leaves his wife's embrace to work for her son, the woman works to keep her marriage chaste, and the contrast is pointed. 'opera ad fabrilia', 'to his smith's work', 'fabrilis' from 'faber', 'smith'. 'surgit', present, vivid. Elision 'oper(a) ad'."""),
(417, 'saxis,',
 "An island beside the Sicanian flank and Aeolian\nrises up, Lipare, with smoking steep rocks,",
 "Beside the coast of Sicily and Aeolian Lipare an island rises, sheer, with its smoking rocks,",
 """A comma-ended unit: the sentence runs to 422 and is split at its comma. 'Insula… erigitur', 'an island rises up'. 'iuxta', 'beside', governs both 'Sicanium… latus', 'the Sicanian side', the flank of Sicily ('Sicani', an old people of the island), and 'Aeoliam… Liparen', 'Aeolian Lipare', 'Liparen' the Greek accusative of 'Lipare', the chief of the Aeolian islands, the home of Aeolus and his winds (1.52). The island meant is the one the ancients called Hiera and Vulcania, today Vulcano, beside Lipari. 'ardua', 'steep', with 'fumantibus… saxis', 'with smoking rocks', ablative of description. No elisions."""),
(422, 'tellus.',
 "under which a cave and, by the Cyclopes eaten out with forges,\ncaverns Aetnaean thunder, and on the anvils mighty blows,\nheard, give back groans, and hiss in the hollows\nthe ingots of the Chalybes, and in the furnaces the fire pants:\nVulcan's home and Vulcanian by name the land.",
 "and beneath it a cave and caverns hollowed out by the Cyclopes' forges, like Etna's own, thunder, and the heavy blows of hammers on anvils are heard and echo with a groan, the bars of Chalybean iron hiss in the hollows, and fire pants in the furnaces: it is Vulcan's home, and the land is called Vulcania after him.",
 """'quam subter', 'beneath which', the preposition after its relative (anastrophe). 'specus et… antra… tonant', 'a cave and caverns thunder'. 'Cyclopum exesa caminis', 'eaten out by the Cyclopes' forges', framing the line: the furnaces have hollowed the rock. 'Aetnaea', 'Aetnaean', 'like Etna's': the Cyclopes' smithy is more usually put under Etna, and Virgil keeps the name for the caverns here. 'validi… ictus', 'mighty blows', 'incudibus', 'on the anvils', 'auditi', 'heard', 'referunt gemitus', 'return groans', echo. 'stricturae Chalybum', 'the ingots of the Chalybes', masses of wrought iron; the Chalybes, a people on the Black Sea, were famous ironworkers, and their name gives the Latin 'chalybs', 'steel' (446). 'ignis anhelat', 'the fire pants', breathing like a living thing under the bellows. 'Volcani domus', in apposition to 'insula'; 'Volcania nomine tellus', 'a land Vulcanian by name'. Elisions 'Cyclop(um) exesa', 'antr(a) Aetnaea'."""),
(423, 'alto.',
 "Hither then the fire-lord from heaven descends on high.",
 "To this place the Lord of Fire now came down from high heaven.",
 """'Hoc', an old form of 'huc', 'hither', not the pronoun. 'ignipotens' is printed here with a small letter, at 414 with a capital; the word is the same title, and the print is kept. 'caelo… ab alto', 'from high heaven', framing 'descendit', the preposition between adjective and noun. No elisions."""),
(425, 'Pyragmon.',
 "Iron were working in the vast Cyclopes cave,\nboth Brontes and Steropes and, naked as to his limbs, Pyragmon.",
 "In the vast cave the Cyclopes were working iron, Brontes and Steropes and Pyragmon, his limbs bare.",
 """'Ferrum exercebant', 'they were working iron', the imperfect of work in progress when the god arrives. 'vasto… in antro', framing 'Cyclopes'. The names are Greek and speak for themselves: Brontes 'Thunderer', Steropes 'Lightning-man', Pyragmon 'Fire-anvil'. Hesiod names the three Cyclopes who made Zeus's thunderbolt Brontes, Steropes and Arges (Theogony, from memory); Virgil's third is his own. 'Brontesque Steropesque', the double '-que'. 'nudus membra', 'naked as to his limbs', the Greek accusative of respect. Elisions 'Ferr(um) exercebant', 'Steropesqu(e) et'."""),
(428, 'manebat.',
 "By these shaped by hands, now a part polished,\na thunderbolt was, of those which from all the sky the father very many\nhurls down on the lands; a part unfinished remained.",
 "Their hands had shaped a thunderbolt, of the kind the Father hurls down in such numbers from every quarter of the sky upon the earth; part of it was already polished, part remained unfinished.",
 """'His informatum manibus… fulmen erat', 'a thunderbolt had been shaped by these men's hands', 'informatum erat' the pluperfect passive split by 'manibus iam parte polita'. 'parte polita', ablative absolute, 'a part having been polished', answered by 'pars inperfecta manebat', 'part remained unfinished'. 'quae plurima', 'of those which… in great numbers': the relative is plural after the singular 'fulmen', thinking of thunderbolts in general. 'toto… caelo', 'from the whole sky', framing 'genitor quae plurima', 'genitor', 'the father', Jupiter. 'deicit', 'throws down'. 'inperfecta' is Greenough's spelling of 'imperfecta', the prefix not assimilated. No elisions."""),
(430, 'austri:',
 "Three of twisted rain rays, three of cloud watery\nthey had added, of ruddy three fire and of winged south wind:",
 "They had added three rays of hail and three of rain-cloud, three of red fire and three of the winged south wind:",
 """The making of the thunderbolt, piece by piece. 'Tris… radios', 'three rays', 'tris' Greenough's form of the accusative 'tres', with the noun understood after each later 'tris'. Each pair is a genitive singular: 'imbris torti', 'of twisted rain', i.e. hail, rain wrung tight into ice (so the ancient commentators explain it); 'nubis aquosae', 'of watery cloud'; 'rutili… ignis', 'of ruddy fire'; 'alitis austri', 'of the winged south wind'. Twelve rays in all, of hail, rain, fire and wind, the stuff of a storm. 'addiderant', pluperfect, 'had (already) added'. The Latin Library prints 'rutuli', which would make the fire 'Rutulian' and gives no sense here; Greenough's 'rutili', 'red', is the reading translated. No elisions."""),
(432, 'iras.',
 "flashes now fearful and sound and fear\nthey were mixing into the work and with flames pursuing wraths.",
 "now they were blending into the work the terrible flashes, the noise, the fear, and wrath that follows in the track of the flames.",
 """'nunc', 'now', at the moment Vulcan arrives: the last ingredients are not matter but effects. 'fulgores… horrificos', 'dreadful flashes'; 'sonitumque metumque', 'both the sound and the fear', the double '-que'; 'iras', 'wraths', 'flammis… sequacibus', 'with pursuing flames', flames that chase what they strike. 'miscebant operi', 'were mixing into the work', 'operi' dative. The Latin Library prints 'terrificos', 'terrifying', for Greenough's 'horrificos'; the sense hardly changes. No elisions."""),
(434, 'urbes;',
 "In a part other for Mars both a chariot and wheels winged\nthey were pressing on, with which he men, with which he rouses cities;",
 "Elsewhere they were hurrying on a chariot for Mars, with its flying wheels, with which he stirs up men and stirs up cities;",
 """'Parte alia', 'in another part' of the workshop. 'Marti', dative, 'for Mars'. 'currumque rotasque', 'both a chariot and wheels', the double '-que', the wheels singled out for their speed: 'volucris', accusative plural in '-is', 'winged', 'flying'. 'instabant', 'were pressing on with', 'were busy on', here with a direct object. 'quibus… quibus', 'with which… with which', anaphora: 'ille', Mars, 'excitat', 'rouses', both 'viros' and 'urbes', the verb shared. Elision 'Part(e) alia'."""),
(438, 'collo.',
 "and the aegis bristling, of roused Pallas the arms,\nvying with scales of serpents and with gold they were polishing,\nand the intertwined snakes and herself on the breast of the goddess\nthe Gorgon, with severed rolling her eyes neck.",
 "and they were vying with one another to burnish the dread aegis, the armour of Pallas when her anger is roused, with serpents' scales and gold, the knotted snakes, and on the goddess's breast the Gorgon herself, rolling her eyes above her severed neck.",
 """'aegida', Greek accusative of 'aegis', the goatskin cloak or breastplate of Pallas Athena (Minerva), fringed with snakes and bearing the Gorgon's head; Homer describes it with the Gorgon at its centre (Iliad 5, from memory). This Pallas is the goddess, not Evander's son, who appears at 466. 'horriferam', 'bristling', 'bringing horror'. 'turbatae Palladis arma', 'the arms of Pallas when roused', in apposition. 'certatim', 'in rivalry'. 'squamis serpentum auroque', 'with scales of serpents and with gold', ablatives of material. 'polibant', the old form of the imperfect, = 'poliebant', 'they were polishing'. 'conexos… anguis', 'the intertwined snakes', accusative plural in '-is'. 'ipsam… Gorgona', 'the Gorgon herself', 'Gorgona' Greek accusative, the head of Medusa cut off by Perseus; 'desecto… collo', ablative absolute, 'her neck severed', framing 'vertentem lumina', 'rolling her eyes', still alive in the metal. Elisions 'aegidaqu(e) horriferam', 'conexosqu(e) anguis', 'ipsamqu(e) in'."""),
(440, 'mentem:',
 "“Take away everything,” he says, “and the begun carry off tasks,\nAetnaean Cyclopes, and here turn your mind:",
 "“Put everything away,” he said, “and take off the work you have begun, Cyclopes of Etna, and turn your minds to this:",
 """Vulcan's speech opens here and runs to 443. 'Tollite cuncta', 'remove everything', the plural imperative to the whole crew. 'inquit', 'he says', interrupting the speech: Greenough prints it with commas and without closing and reopening the marks, his habit (as 8.351); l and i supply them. 'coeptos… labores', 'the tasks begun', framing 'auferte', 'take away'. 'Aetnaei Cyclopes', vocative, 'Cyclopes of Etna', their usual home. 'huc advertite mentem', 'turn your mind hither', the singular 'mentem' for the attention of all. Elisions 'cunct(a) inquit', 'coeptosqu(e) auferte'."""),
(441, 'viro.',
 "arms for a fierce must be made man.",
 "arms must be made for a fierce warrior.",
 """'arma… facienda (sunt)', 'arms are to be made', the gerundive of obligation with 'sunt' left out. 'acri… viro', 'for a fierce man', dative, framing 'facienda'. Vulcan does not name him: Aeneas, as at the start of the poem, is 'the man' ('virum', 1.1), and 'arma' and 'viro' stand in the line together. Elision 'arm(a) acri'."""),
(442, 'magistra.',
 "Now of strength there is need,\nnow of hands swift, now of all art your master.",
 "Now there is need of strength, now of quick hands, now of all your mastery of the craft.",
 """'usus (est)', 'there is need', with the ablative 'viribus', 'of strength', and then of 'manibus rapidis', 'swift hands', and 'omni… arte magistra', 'all your master craft', 'magistra' used as an adjective, 'art as a teacher', 'master skill'. 'nunc… nunc… nunc', anaphora, the orders rapping out. No elisions."""),
(443, 'effatus;',
 "Hurl headlong delays.” No more having spoken;",
 "Make haste, no delay!” He said no more;",
 """The print has 'moras. ”Nec', with a space before the closing mark and none after it, a misprint for 'moras.” Nec', corrected here; t keeps the print, because t must match the pinned source. Because the mark is joined to 'Nec', this unit also carries 'Nec plura effatus', as at 8.404. 'Praecipitate moras', 'throw delays headlong', a vivid way of saying 'make haste'. Vulcan's speech ends. 'Nec plura effatus (est)', 'and he spoke no more', from the deponent 'effor'. Elision 'plur(a) effatus'."""),
(445, 'sortiti.',
 "but they\nmore swiftly bent to it all, and equally the labour\nshared by lot.",
 "and they all fell to the work at once, sharing out the labour equally by lot.",
 """'at illi', 'but they', the Cyclopes. 'ocius', 'quicker', comparative adverb, 'at once', 'with all speed'. 'incubuere' = 'incubuerunt', 'they bent to it', 'leaned on', the '-ere' perfect (you know it by now). 'pariter… sortiti (sunt)', 'they shared out by lot equally', 'sortior', deponent, 'to cast lots for', with 'laborem' as object. Elision 'incubuer(e) omnes'."""),
(446, 'liquescit.',
 "Flows bronze in streams and of gold the metal,\nand wound-making steel in the vast furnace melts.",
 "Bronze flows in streams, and gold, and the steel that deals wounds melts in the huge furnace.",
 """'Fluit aes rivis', 'bronze flows in streams', 'rivis' ablative of manner. 'auri… metallum', 'the metal of gold', just 'gold'. 'volnificus', Greenough's spelling of 'vulnificus' ('volnus' for 'vulnus' again), 'wound-making', a compound in the old epic manner. 'chalybs', 'steel', from the Chalybes (421). 'liquescit', 'grows liquid', an inceptive verb. Bronze, gold and steel: in Iliad 18 Hephaestus throws bronze, tin, gold and silver into the fire for Achilles' armour (from memory). No elisions."""),
(449, 'impediunt.',
 "Huge a shield they shape, one against all\nthe weapons of the Latins, and sevenfold with circles circles\nthey interlock.",
 "They shape a huge shield, a match by itself for all the weapons of the Latins, and bind together seven layers of circles, one upon another.",
 """The print has 'Ingentum', a misprint for 'Ingentem', corrected here; t keeps the print, because t must match the pinned source. No Latin word 'ingentum' agrees with 'clipeum': the accusative of 'ingens' is 'ingentem', which the Latin Library prints and the metre allows equally. 'clipeum informant', 'they shape a shield', the shield whose pictures will close the book. 'unum omnia contra tela Latinorum', 'one against all the weapons of the Latins', 'unum' and 'omnia' set side by side, 'contra' after its noun. 'septenosque orbibus orbes impediunt', 'and they interlock sevenfold circles with circles', seven layers of metal plate fastened one over another, 'orbibus orbes' a striking repetition. The sevenfold shield is Ajax's in Homer (Iliad 7, from memory); Achilles' new shield has five layers (Iliad 18 and 20). Elisions 'clipe(um) informant', 'un(um) omnia', 'septenosqu(e) orbibus'."""),
(451, 'lacu.',
 "Others with windy bellows the airs\ntake in and give back, others hissing dip\nbronzes in the trough.",
 "Some take in the air and send it out again with bellows full of wind; others dip the hissing bronze into the water-trough.",
 """'Alii… alii', 'some… others'. 'ventosis follibus', 'with windy bellows', ablative of means; 'auras accipiunt redduntque', 'take in and give back the breezes', the bellows filling and emptying. Hephaestus works twenty bellows at once in Iliad 18 (from memory). 'stridentia… aera', 'hissing bronzes', 'aera' neuter plural of 'aes', the hot metal hissing as it is quenched; 'tingunt… lacu', 'dip in the trough', 'lacus' here a vat of water. No elisions."""),
(451, 'antrum.',
 "Groans with the set-on anvils the cave.",
 "The cave groans under the weight of the anvils set upon it.",
 """'Gemit… antrum', 'the cave groans', verb first and subject last, framing the line's second half. 'impositis incudibus', 'with the anvils set upon it', ablative of cause: the cave's floor groans under the anvils and the blows. No elisions."""),
(453, 'massam.',
 "They among themselves with much force their arms raise\ninto rhythm, and turn with gripping tongs the mass.",
 "They raise their arms with mighty force, one after another, in time, and turn the glowing lump with the gripping tongs.",
 """'Illi', 'they', the Cyclopes at the anvils. 'inter sese', 'among themselves', 'by turns'. 'multa vi', 'with much force'. 'bracchia tollunt in numerum', 'raise their arms in rhythm', 'numerus' the beat: the hammer-blows fall in time. 'tenaci forcipe', 'with gripping tongs', framing 'versant… massam', 'turn the mass' of metal on the anvil. Virgil had used nearly the same two lines of the Cyclopes in a simile for bees in the Georgics (Book 4, from memory). Elision 'Ill(i) inter'."""),
(456, 'cantus.',
 "These things while the father on the Aeolian hastens, the Lemnian, shores,\nEvander from his humble roof the light rouses, kindly,\nand of morning the birds' under the eaves songs.",
 "While the Lemnian father was pressing on with this work on the Aeolian shores, the kindly light of day and the morning songs of the birds under the eaves roused Evander in his humble house.",
 """A new paragraph in Greenough: the scene moves back to Pallanteum. 'Haec… properat dum', 'while (he) hastens these things', 'dum' postponed to fifth place; 'properare' with an object, 'to hurry on' a task. 'pater… Lemnius', 'the Lemnian father', Vulcan, from Lemnos, where Hephaestus fell when Zeus threw him out of heaven (Iliad 1, from memory), and where he was worshipped. 'Aeoliis… oris', 'on the Aeolian shores', framing the clause. 'Euandrum… lux suscitat alma', 'the nurturing light rouses Evander'; 'Eu-' is one syllable. 'ex humili tecto', 'from his lowly roof', the humble house of 8.359–368. 'matutini volucrum sub culmine cantus', 'the morning songs of birds under the roof-ridge', 'matutini… cantus' framing 'volucrum sub culmine'. Elision 'Euandr(um) ex'."""),
(458, 'plantis;',
 "Rises the old man and with a tunic draws on his limbs,\nand Tyrrhenian of his feet he puts round bonds the soles;",
 "The old man rose, put his tunic on over his limbs and tied Etruscan sandals round the soles of his feet;",
 """'Consurgit senior', 'the old man rises', 'senior' as often for 'old man', not a comparison. 'tunica… inducitur artus', 'he is drawn on as to his limbs with a tunic', i.e. 'he puts a tunic on his limbs', the passive used like the Greek middle voice with an accusative ('artus') of the part concerned; you have seen this with 'nudus membra' (425). 'Tyrrhena… vincula', 'Tyrrhenian bonds', the straps of Etruscan sandals; Etruscan sandals were a known fashion. 'pedum… plantis', 'the soles of his feet', dative with 'circumdat', 'puts round'. Elision 'tunicaqu(e) inducitur'."""),
(460, 'retorquens.',
 "then to his side and shoulders a Tegean he fastens sword,\nhanging down from the left a panther's hide throwing back.",
 "then he buckled his Tegean sword to his side, with its strap over his shoulder, and threw back the panther-skin that hung down on his left.",
 """'tum', 'then', the dressing done in order, like a Homeric hero's arming. 'lateri atque umeris', 'to his side and shoulders', datives with 'subligat', 'fastens beneath', the sword hanging at the side from a baldric over the shoulder. 'Tegeaeum… ensem', 'a Tegean sword', from Tegea in Arcadia, Evander's homeland. 'demissa ab laeva', 'hanging down from the left', with 'pantherae terga', 'the panther's hide', poetic plural 'terga', 'backs', for the skin; 'retorquens', 'twisting back', throwing it back over his shoulder. Elisions 'later(i) atque', 'atqu(e) umeris', 'demiss(a) ab'."""),
(462, 'erilem.',
 "Nor not also twin guardians from the threshold high\ngo before and the step dogs accompany of their master.",
 "Two watchdogs too went before him from the high threshold and kept pace with their master's steps.",
 """'Nec non et', 'and also', 'and besides', a double negative making a positive. 'gemini custodes… canes', 'twin guardians… dogs', the noun held back to the second line. 'limine ab alto', 'from the high threshold', the preposition between noun and adjective. 'gressum… erilem', 'the master's step', framing 'canes comitantur'; 'erilis' is 'herilis', from 'erus' ('herus'), 'master'. Telemachus goes to the assembly with two dogs at his side (Odyssey 2, from memory): the homely detail is Homeric. Elision 'limin(e) ab'."""),
(464, 'heros.',
 "Of his guest Aeneas the abode and the private part he was seeking,\nof their talk mindful and of the promised gift, the hero.",
 "The hero was making for the lodging and private quarters of his guest Aeneas, mindful of their talk and of the help he had promised.",
 """'Hospitis Aeneae', 'of his guest Aeneas', genitive with both 'sedem' and 'secreta', 'the dwelling and the private part' of the house where Aeneas slept. 'petebat', imperfect, 'was making for'. 'sermonum memor', 'mindful of their conversations', and 'promissi muneris', 'of the promised gift', the help Evander promised at their first meeting (8.169–171). 'heros', 'the hero', held to the end: Evander. Elision 'sed(em) et'."""),
(465, 'agebat.',
 "No less Aeneas himself early in the morning was stirring.",
 "No less early was Aeneas astir.",
 """'Nec minus', 'no less', litotes. 'se… agebat', 'was moving himself', 'was on the move'. 'matutinus', 'in the morning', an adjective where English uses an adverb, common in Latin with words of time. No elisions."""),
(466, 'Achates.',
 "Son to this one Pallas, to that one companion went Achates.",
 "With the king went his son Pallas, with Aeneas his comrade Achates.",
 """'Filius huic Pallas, illi comes ibat Achates', 'his son Pallas (went) with this one, Achates as companion with that one', 'ibat' shared by both halves, the two clauses balanced. 'huic' and 'illi' are datives of reference, and by sense 'huic' is Evander (Pallas is his son) and 'illi' Aeneas, against the usual rule that 'hic' means the nearer, latter name. 'Achates', Aeneas's faithful companion since Book I. No elisions."""),
(468, 'fruuntur.',
 "Having met they join right hands and in the middle sit down\nof the house, and permitted at last talk enjoy.",
 "They met and clasped right hands, sat down in the middle of the house, and at last enjoyed the free talk now allowed them.",
 """'Congressi', 'having met', perfect participle of the deponent 'congredior'. 'iungunt dextras', 'they join right hands', the gesture of friendship and good faith. 'mediis… aedibus', 'in the middle of the house', the hall or courtyard, framing 'residunt'. 'licito… sermone', 'permitted talk', ablative with 'fruuntur', 'enjoy' ('fruor' takes the ablative): talk now free, the day before having been taken up with the feast and the rites of Hercules. No elisions."""),
(469, 'haec:',
 "The king first these words:",
 "The king spoke first:",
 """A half-line, one of those Virgil left unfinished in the unrevised poem. 'Rex prior', 'the king first', 'haec', 'these things', with the verb of speaking left out ('Aeolus haec contra'). No elisions."""),
(473, 'vires:',
 "“Greatest of the Teucrians leader, whom being safe never\nthe power indeed of Troy conquered or its realms will I confess,\nto us for of war help in respect of a name so great\nslight is the strength:",
 "“Greatest leader of the Teucrians — for while you live I will never admit that Troy's power or kingdom is overthrown — we have little strength to help you in war, little for a name so great:",
 """Evander's speech opens here and runs to the end of this part. 'Maxume', vocative of 'maxumus', Greenough's old spelling of 'maxime' ('maxumus' for 'maximus' again). 'Teucrorum ductor', 'leader of the Teucrians'; 'Teu-' is one syllable. 'quo sospite', ablative absolute, 'you being safe', 'while you survive'. 'res… Troiae victas aut regna fatebor', 'I will admit that Troy's state or realms are conquered', 'victas' with both nouns. 'equidem', 'I for my part'. 'nobis… exiguae vires (sunt)', 'to us is slight strength', a dative of possession, 'we have little strength'. 'ad belli auxilium', 'for help in war'. 'pro nomine tanto', 'in proportion to so great a name', Aeneas's fame. Elision 'bell(i) auxilium'."""),
(474, 'armis.',
 "on this side by the Tuscan we are shut in river,\non that the Rutulian presses and the wall echoes round with arms.",
 "on one side the Tuscan river hems us in, on the other the Rutulian presses hard and rings our walls with the clash of arms.",
 """'hinc… hinc', 'on this side… on that', anaphora. 'Tusco… amni', 'by the Tuscan river', the Tiber, the boundary of Etruria, framing 'claudimur'. 'Rutulus', 'the Rutulian', collective singular for Turnus's people. 'murum circumsonat armis', 'makes the wall resound all round with arms'. No elisions."""),
(477, 'ostentat:',
 "But to you I huge peoples and rich in kingdoms\nto join a camp am preparing, which unlooked-for chance as a deliverance\nholds out:",
 "But I am preparing to join to you mighty peoples and an army rich in kingdoms, a deliverance which a chance no one foresaw now holds out:",
 """'Sed tibi ego', 'but to you I', the pronouns side by side. 'ingentis populos', 'huge peoples', accusative plural in '-is'. 'opulenta… regnis… castra', 'a camp rich in kingdoms', the Etruscan army drawn from many cities, 'regnis' ablative with an adjective of plenty. 'iungere… paro', 'I am preparing to join'. 'quam fors inopina salutem ostentat', 'which salvation unexpected chance shows', the antecedent drawn into the relative clause: 'a salvation which chance holds out'. Elisions 'tib(i) ego', 'eg(o) ingentis'."""),
(477, 'adfers.',
 "with the fates here you demanding you bring yourself.",
 "you come here at the call of the fates.",
 """'fatis… poscentibus', ablative absolute, 'the fates demanding (you)', framing 'huc te'. 'adfers', 'you bring yourself', with 'te', 'you come'; 'adfero' is Greenough's unassimilated spelling of 'affero'. No elisions."""),
(480, 'Etruscis.',
 "Not far from here, on rock is inhabited, founded ancient,\nof the city Agyllan the seat, where the Lydian once\nrace, in war renowned, on the ridges settled Etruscan.",
 "Not far from here, founded on ancient rock, stands the city of Agylla, where long ago a Lydian people famous in war settled on the Etruscan hills.",
 """'Haud procul hinc', 'not far from here'. 'saxo… fundata vetusto', 'founded on ancient rock', framing 'incolitur', 'is inhabited'. 'urbis Agyllinae sedes', 'the seat of the Agyllan city', the genitive of definition: the city itself. Agylla is the Greek name of Caere (Cerveteri), north-west of Rome. 'Lydia… gens', 'the Lydian race', framing the next clause: the ancients held that the Etruscans came from Lydia in Asia Minor (Herodotus, Book 1, from memory). 'bello praeclara', 'famous in war'. 'iugis… Etruscis', 'on the Etruscan hills', framing 'insedit', 'settled'. Elision 'sax(o) incolitur'."""),
(482, 'armis.',
 "This, many flourishing years, a king afterwards with proud\nrule and with savage held, Mezentius, arms.",
 "It had flourished for many years when King Mezentius took hold of it with arrogant rule and savage arms.",
 """'Hanc', the city, 'multos florentem annos', 'flourishing for many years', accusative of duration. 'rex deinde', 'a king afterwards', with the name held back: 'Mezentius', 'the despiser of the gods' of the catalogue (7.648). 'deinde', two syllables here, 'dein-de'. 'superbo imperio et saevis… armis', 'with proud rule and savage arms', 'superbo imperio' framing the line-break, 'saevis… armis' framing 'tenuit Mezentius'. 'superbus' is the word Romans used of tyrants: Tarquinius Superbus. Elisions 'florent(em) annos', 'imperi(o) et'."""),
(484, 'effera?',
 "Why should I recall the unspeakable slaughters, why the deeds of the tyrant\nsavage?",
 "Why should I tell of his unspeakable murders, or the brutal acts of the tyrant?",
 """'Quid memorem', 'why should I recount', the deliberative subjunctive, introducing the device of passing over what one then tells (praeteritio). 'infandas caedes', 'unspeakable slaughters'. 'facta tyranni effera', 'the savage deeds of the tyrant', 'effera' held to the next line for weight. Elision 'memor(em) infandas'."""),
(484, 'reservent!',
 "May the gods for his head itself and his race keep them in store!",
 "May the gods keep the like in store for his own head and his children's!",
 """'Di', 'gods', = 'dei'. 'reservent', subjunctive of wish, 'may they keep in store', with the object understood: the same horrors. 'capiti ipsius', 'for his own head', the head standing for the person, a form of curse; 'generi', 'for his race', his line, his son Lausus (7.649–654). Elision 'capit(i) ipsius'."""),
(488, 'necabat.',
 "Dead nay even he used to join bodies to living men,\nsetting together both hands to hands and mouths to mouths,\na kind of torture, and with gore and with corruption flowing,\nin an embrace wretched, thus by a long death he killed.",
 "He would even bind the dead to the living, fitting hands to hands and mouths to mouths, a torture of his own devising, and so, as they oozed with gore and corruption in that horrible embrace, he would kill them by a slow death.",
 """'quin etiam', 'nay even', a step up from 'quid memorem': this is what he did. 'Mortua… corpora', 'dead bodies', framing 'quin etiam iungebat', and 'vivis', 'to the living', the iterative imperfect 'iungebat', 'used to join'. 'componens', 'setting together'. 'manibusque manus atque oribus ora', 'hands to hands and mouths to mouths', datives and accusatives side by side, the bodies fitted limb to limb. 'tormenti genus', 'a kind of torture', in apposition to the whole act. 'sanie taboque fluentis', 'flowing with gore and corruption', 'fluentis' accusative plural agreeing with the victims understood; 'sanies' is the bloody matter of wounds, 'tabum' the putrid fluid of decay, here the corpse's. 'complexu in misero', 'in the wretched embrace'. 'longa… morte', 'by a long death', 'necabat', 'he killed'. Cicero, in a lost work quoted by Augustine, likened the soul bound to the body to the captives Etruscan pirates killed this way (from memory). Elisions 'atqu(e) oribus', 'complex(u) in'."""),
(491, 'iactant.',
 "but wearied at last the citizens, him raging unspeakable things,\nin arms surround, both himself and his house,\ncut down his followers, fire to the roof-tops hurl.",
 "But at last the citizens could bear no more; they took up arms and surrounded him in his monstrous frenzy, himself and his house, cut down his followers and hurled fire on to the roof.",
 """The print has 'at', lowercase after the full stop that ends 488, a misprint for 'At', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital. 'fessi tandem cives', 'the citizens, weary at last'. 'infanda furentem', 'raging unspeakable things', an internal accusative with 'furo'. 'armati', 'armed', 'circumsistunt', 'surround'. 'ipsumque domumque', 'both himself and his house', the double '-que'. 'obtruncant socios', 'they butcher his followers', his guards. 'ignem ad fastigia iactant', 'they throw fire to the gables'. The historic presents quicken the pace. Elision 'ign(em) ad'."""),
(493, 'armis.',
 "He amid the slaughter into the Rutulians' having slipped out fields\nfled for refuge and by Turnus was defended, his host's, arms.",
 "In the midst of the slaughter he slipped away and fled for refuge to the land of the Rutulians, where the arms of his friend Turnus protect him.",
 """'Ille', Mezentius. 'inter caedem', 'amid the slaughter'. 'Rutulorum… in agros', 'into the fields of the Rutulians', framing 'elapsus', 'having slipped away'. 'confugere' and 'defendier' are historic infinitives, used like a past indicative in lively narrative: 'he fled and was protected'. 'defendier' is the old present passive infinitive in '-ier', = 'defendi', an archaism Virgil keeps for weight. 'Turni… hospitis armis', 'by the arms of Turnus his host', ablative of means; 'hospes' is a guest-friend, the bond of hospitality. Elisions 'Ill(e) inter', 'Rutulor(um) elapsus', 'confuger(e) et'."""),
(494, 'iustis:',
 "Therefore all in furies rose up Etruria righteous:",
 "So all Etruria has risen in just rage:",
 """'Ergo', 'therefore'. 'omnis… Etruria', 'all Etruria', framing the verb. 'furiis… iustis', 'with just furies', framing the line: 'furiae' is usually madness, here a fury the speaker calls just. 'surrexit', 'has risen'. Elision 'Erg(o) omnis'."""),
(495, 'reposcunt.',
 "the king to punishment with present Mars they demand back.",
 "they demand the king back for punishment, with war on the spot.",
 """'regem ad supplicium… reposcunt', 'they demand the king back for punishment', from Turnus, who shelters him. 'praesenti Marte', 'with Mars at hand', 'with instant war', ablative of manner; Mars for war, as often (metonymy). Elision 'reg(em) ad'."""),
(496, 'addam.',
 "To these I you, Aeneas, as leader thousands will add.",
 "To these thousands I shall give you, Aeneas, as their leader.",
 """The print has 'his', lowercase after the full stop that ends 495, a misprint for 'His', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital. 'his… milibus', 'to these thousands', dative with 'addam', framing the line. 'te… ductorem', 'you as leader', predicative. 'Aenea', vocative of 'Aeneas', the Greek form. Elision 't(e) Aenea'."""),
(498, 'iubent;',
 "For all along the shore roar, packed close, the ships,\nand the standards to carry forward they bid;",
 "For along the whole shore their ships lie packed close together and roar with men who call for the standards to advance;",
 """The print has 'Signaque', with a capital in mid-sentence (497 ends with no stop), a misprint for 'signaque', corrected here; t keeps the print, because t must match the pinned source. 'namque', 'for', giving the reason for 'his milibus'. 'Toto… litore', 'along the whole shore', framing 'fremunt condensae', 'roar, crowded close'; 'puppes', 'sterns', for the ships, and the ships for the men aboard. 'signa ferre iubent', 'they bid carry the standards', the military order to advance. No elisions."""),
(502, 'gentem:',
 "holds them back an aged soothsayer,\nfates chanting: ‘O of Maeonia chosen youth,\nflower of the old and valour of men, whom a just against the foe\ncarries resentment and with deserved fires Mezentius with wrath,\nfor no Italian is it right so great to subdue a race:",
 "but an aged soothsayer holds them back, chanting the decrees of fate: ‘Chosen warriors of Maeonia, the flower and valour of an ancient people, carried against the enemy by just resentment and set ablaze by Mezentius with a wrath he has earned, no man of Italy may master a nation so great:",
 """The print has '“fata canens, O Maeoniae', an opening speech mark at the head of the line before 'fata', a misprint for 'fata canens: “O Maeoniae', the mark belonging before 'O', where the soothsayer's words begin, as at 6.46, 6.52 and 7.121; t keeps the print, because t must match the pinned source. Within Evander's speech l and i give the soothsayer's words in single marks, closing them at 'duces' (503), where Greenough prints no mark. 'retinet', 'holds (them) back'. 'longaevus haruspex', 'an aged soothsayer'; the 'haruspex' read the entrails of victims, an Etruscan art. 'fata canens', 'chanting the fates', prophecy being sung. 'Maeoniae', 'of Maeonia', the old name of Lydia: the Etruscans as Lydians (480). 'delecta iuventus', 'chosen youth', the army. 'flos veterum virtusque virum', 'the flower and valour of men of old', 'virum' = 'virorum'. 'quos… fert dolor', 'whom resentment carries', 'iustus… dolor' framing the clause, 'in hostem', 'against the enemy'. 'merita… ira', 'with merited wrath', framing 'accendit Mezentius', 'Mezentius kindles': the wrath he deserves. 'nulli fas Italo', 'it is right for no Italian', dative. 'subiungere', 'to bring under the yoke', 'sub-iun-ge-re'. Elision 'merit(a) accendit'."""),
(503, 'duces;',
 "foreign choose leaders.’",
 "choose foreigners to lead you.’",
 """'externos… duces', 'foreign leaders', framing 'optate', 'choose', the plural imperative. The oracle's words end here, and they point at Aeneas, the stranger whom Latinus's oracle also foretold (7.98, 'externi venient generi'). The print has no mark here; l and i close the soothsayer's words. No elisions."""),
(504, 'divom.',
 "then the Etruscan sat down\nin this the line plain, by the warnings terrified of the gods.",
 "Then the Etruscan army settled down on this plain, daunted by the warnings of the gods.",
 """'tum', 'then', after the prophecy. 'Etrusca… acies', 'the Etruscan battle-line', framing 'resedit hoc', 'sat down', 'came to rest', and 'hoc… campo', 'on this plain', near by. 'monitis exterrita divom', 'terrified by the warnings of the gods', 'divom' = 'divorum', Greenough's old genitive plural (as always). Elision 't(um) Etrusca'."""),
(507, 'capessam.',
 "Himself envoys to me and of the kingdom the crown\nwith the sceptre sent, and entrusts the insignia, Tarchon,\nthat I should come up to the camp and the Tyrrhenian kingdom take up.",
 "Tarchon himself has sent envoys to me with the crown and sceptre of the kingdom, and hands over to me the emblems of royalty, asking me to come to the camp and take up the throne of Etruria.",
 """'Ipse… Tarchon', 'Tarchon himself', framing the sentence; Tarchon, the Etruscan leader who will join Aeneas in Book X. 'oratores', 'envoys', 'spokesmen'. 'regni… coronam cum sceptro', 'the crown of the kingdom with the sceptre'. 'mandat… insignia', 'entrusts the insignia', with 'succedam… capessam', 'that I should approach… and take up', subjunctives depending on 'mandat' without 'ut', as often after verbs of ordering. 'succedam castris', 'that I should come to the camp', dative with a compound verb. 'Tyrrhena… regna', 'the Tyrrhenian kingdom', poetic plural. 'capessam', 'take in hand', a desiderative of 'capio'. Elisions 'Ips(e) oratores', 'mandatqu(e) insignia'."""),
(509, 'vires.',
 "But for me slow with chill and with ages worn out old age\ngrudges the command, and too late for brave deeds my strength.",
 "But old age, slow with the chill of years and worn out by long time, begrudges me the command, and my strength comes too late for deeds of courage.",
 """'Sed mihi… senectus invidet imperium', 'but old age grudges me the command', 'invideo' with a dative of the person and an accusative of the thing, a poetic construction. 'tarda gelu', 'slow with cold', the cold of old blood. 'saeclis… effeta', 'worn out by ages', 'effetus', 'exhausted', literally 'past bearing'. 'seraeque ad fortia vires', 'and strength too late for brave deeds', a second subject of 'invidet': his strength comes too late in life. Elisions 'saeclisqu(e) effeta', 'seraequ(e) ad'."""),
(511, 'traheret.',
 "My son I would urge on, if not, mixed from a mother Sabine,\nfrom here a part of his fatherland he drew.",
 "I would urge my son to take it, were it not that his Sabine mother has mixed his blood, and he draws part of his descent from this land.",
 """The print has 'natum', lowercase after the full stop that ends 509, a misprint for 'Natum', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital. 'natum exhortarer', 'I would urge on my son', the imperfect subjunctive of a present unreal condition, with 'ni… traheret', 'if he did not draw'. 'mixtus matre Sabella', 'mixed by a Sabine mother', 'Sabellus' an Oscan people's name used for Sabine. 'hinc', 'from here', from Italy: being half Italian, Pallas is barred by the prophecy ('nulli fas Italo', 502). 'partem patriae', 'a part of his fatherland', his country of origin. Elision 'nat(um) exhortarer'."""),
(513, 'ductor.',
 "You, whose both years\nand race fate favours, whom the divine powers demand,\nstep in, O of Teucrians and Italians bravest leader.",
 "You, whose years and whose birth fate favours, whom the gods call for, take up the task, bravest leader of Trojans and Italians alike.",
 """The print has 'indulgent', a plural verb with the singular subject 'fatum', a misprint for 'indulget', corrected here; t keeps the print, because t must match the pinned source. The Latin Library prints 'indulget', and the metre allows either. 'cuius et annis et generi', 'to whose years and to whose race', datives with 'indulget', 'is kind to', 'favours': Aeneas is young enough and foreign enough. 'quem numina poscunt', 'whom the gods demand', echoing 'fatis… poscentibus' (477). 'ingredere', imperative of the deponent 'ingredior', 'step in', 'take it on'. 'Teucrum atque Italum', genitives plural, 'of Teucrians and Italians', the old short forms; Aeneas will lead both. 'fortissime ductor', vocative, ringing back to 'Maxume… ductor' (470). Elisions 'fat(um) indulgent', 'Teucr(um) atque', 'atqu(e) Italum'."""),
(515, 'adiungam;',
 "This one to you besides, the hope and comfort of us,\nPallas I will join;",
 "Besides, I will join to you this boy, my hope and comfort, Pallas;",
 """The print has 'hunc', lowercase after the full stop that ends 513, a misprint for 'Hunc', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital. 'hunc… Pallanta', 'this (one)… Pallas', framing the clause, 'Pallanta' the Greek accusative. 'praeterea', 'besides'. 'spes et solacia nostri', 'the hope and comforts of us', in apposition, 'nostri' the genitive of 'nos' used for 'me', 'my'. 'adiungam', 'I will join', 'ad-iun-gam'. Evander's offer of his son is the gift whose cost Book XI will count. Elision 'Pallant(a) adiungam'."""),
(517, 'annis.',
 "under you to bear as master\nsoldiering and the heavy of Mars work, your to behold deeds\nlet him grow used, from first, and you let him admire, years.",
 "under you as his teacher let him grow used to soldiering and the heavy work of war, to watching what you do, and let him look up to you from his earliest years.",
 """'sub te… magistro', 'under you as master', ablative absolute in effect, 'with you as his teacher'. 'adsuescat', 'let him grow used', jussive subjunctive, governing three infinitives: 'tolerare militiam', 'to endure soldiering', 'grave Martis opus', also with 'tolerare', 'the heavy work of Mars', war, and 'tua cernere facta', 'to see your deeds'. 'et te miretur', 'and let him admire you', a second jussive. 'primis… ab annis', 'from his first years', framing the clause: he is still young. 'adsuescat' is Greenough's spelling of 'assuescat', with consonantal 'u', 'ad-sues-cat'. Elision 'militi(am) et'."""),
(519, 'Pallas.”',
 "Arcadian to him horsemen two hundred, the strength of our youth\nchosen, I will give, and as many in his own to you name Pallas.”",
 "To him I will give two hundred Arcadian horsemen, the chosen strength of our young men, and Pallas will give you as many more in his own name.”",
 """'Arcadas… equites', 'Arcadian horsemen', 'Arcadas' the Greek accusative plural, framing 'huic', 'to him'. 'bis centum', 'twice a hundred'. 'robora pubis lecta', 'chosen strengths of the youth', in apposition: 'robur', 'oak', then 'hardness', 'strength', here the best of the fighting men. 'dabo', 'I will give'. 'totidemque', 'and as many', with 'dabit' understood: 'Pallas (will give) you as many in his own name', a gift from the son as well as the father, four hundred in all. 'suo… nomine', framing 'tibi'. Evander's speech ends, and Greenough closes the mark; the scene goes on in the next part. No elisions."""),
]

P = A.part('aeneid-061'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
